<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue';import {useI18n} from 'vue-i18n';import {useAuthStore} from '../../stores/auth';import {operationRequest} from '../../services/admin/operations';const {t,locale}=useI18n(),auth=useAuthStore(),rows=ref<any[]>([]),failed=ref(false);let loaded=false;const c=new AbortController();watch(()=>auth.verifiedAdmin,value=>{if(value&&!loaded)void operationRequest('/operations/services',c.signal).then(r=>{rows.value=r.items;loaded=true}).catch(()=>{failed.value=true})},{immediate:true});onBeforeUnmount(()=>c.abort());
</script>
<template><section><h2>{{t('operations.services')}}</h2><p v-if="failed" role="alert">{{t('operations.unavailable')}}</p><ul><li v-for="row in rows" :key="row.id"><RouterLink :to="'/admin/services/manage/'+row.id">{{row.data['name_'+locale]}}</RouterLink> · {{t(row.data.active&&row.data.booking_enabled?'operations.booking':'simple.inactive')}} · {{t(row.data.editorial_key?'simple.websitePrice':'operations.noSource')}}</li></ul><RouterLink to="/admin/services/new">{{t('simple.addService')}}</RouterLink></section></template>
<style scoped>h2{font-size:1.5rem;margin-bottom:12px}section{margin-top:32px}a{text-decoration:underline;display:inline-block;min-height:44px;padding:12px 0}li{padding:8px 0}</style>
